#!/usr/bin/env python3
# =====================================================================
#  apply_gtt_monitor_proof.py  —  fence GTT_MONITOR_PROOF_20261115
#  REQUIRES main at v11.7.9 (BROKER_TRUTH_20261114 + opposite sides).
#  1 of 4 — then apply_gtt_kill_list.py, apply_flat_needs_proof.py,
#  apply_ledger_boot.py (in that order).
#
#  ⚠ LIVE ORDER PATH — the two GTT monitors (Icarus, Timberwolf).
#
#  Found by the fleet assurance run of 15 Nov 2026; every case is
#  reproduced in app/engine/test_fleet_adversarial.py (fails on main).
#
#  D1  Icarus, stop GAPS through on a strike another strategy also holds:
#      the tick stop saw "GTT triggered" and deferred to the monitor; the
#      monitor could not attribute the net position and waited forever. The
#      short stayed open, the GTT's limit rested, nobody was paged.
#      (new in v11.7.9 — v11.7.8 escalated.)
#      → the monitor reads the GTT's OWN order: visible and not filled =
#        escalate now (cancel it, market-out own quantity). If that order
#        cannot be cancelled: no second buy, one page.
#  D2  A triggered GTT that had not listed its order yet was resolved from
#      "any COMPLETE buy on the symbol" — on a shared strike that is another
#      strategy's buy-back. Icarus booked Tigris's fill as its own stop while
#      its own limit still rested.
#      → every order the app places is noted (ExecutionRouter →
#        broker_truth.note_app_order); a GTT fill / manual exit is by
#        definition NOT one of them; a claimed order serves one leg only.
#  D5a "No exit order, no booking" held only on the "GTT missing" branch; the
#      "triggered / disabled" branch still booked BROKER_EXIT at a fallback
#      price. → same rule on both branches.
#  D6  A GTT listed as cancelled / rejected / expired / deleted counted as
#      protection. → only an armed GTT does; the others raise the naked alert.
#      An unattributable triggered GTT is paged once (was: silent retry).
#
#   ic_gtt_monitor.py, tma2_gtt_monitor.py   the rules above
#   broker_truth.py        app-order registry (note / claim / app_order_ids)
#   execution_router.py    notes every order it places (pass-through)
#   ic_group_manager.py    note_exit_fills (partial GTT fill before cancel)
#   test_ic_engine_monitor_eod.py  one test updated: fallback booking → no booking
#   test_fleet_live.py     resets the registry per fake broker
#   test_fleet_adversarial.py  NEW — 34 adversarial checks + 120 random
#                              fault days (this script gates on its stage 1)
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_gtt_monitor_proof.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then (after all four): ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "GTT_MONITOR_PROOF_20261115"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "e618c12e3ea3dccdc512d4364740c87e40c444e4d1d81c84b9bd12fe8ab02dae", "new": "f410bb9724170ade13cc9d6c1ccc97998c58393a8647db489bbfc86ee13ae3e5", "blob": ""}, {"path": "backend/app/engine/ic/ic_gtt_monitor.py", "orig": "04a3ed0961efacef411a3f1c0a86cd71ed9295cd4e4f90164a2e65f3bd9fdd04", "new": "05f19e2a11be846bca465d069345c40eb820eb4e2ac5fa324659b4bb184229aa", "blob": ""}, {"path": "backend/app/engine/ic/test_ic_engine_monitor_eod.py", "orig": "efde0fd1b580ceba04d2a52d1b3a54aa372fbecc33e0118b3e3c76c9fd00ae32", "new": "3fb094465d65c21224146b507a3aebe15f3e9f675677dc660b277ef978eaec7f", "blob": ""}, {"path": "backend/app/engine/test_fleet_adversarial.py", "orig": null, "new": "d79f47c1d21c536a582184ae460714632211bcdf8eff612612da2c9dc3a7ce1d", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_gtt_monitor.py", "orig": "d3e9137392a33421970459528d7f0f0405473c4a3cb736a8baf64db18639d0b0", "new": "4895535e3f06598eacbc8e9ba4d1bc72a4992204adc0ecbac4925c11c4dc07f1", "blob": ""}, {"path": "backend/app/execution/broker_truth.py", "orig": "580de64536d6472c76099d56db4ef9880135640209591f2df248e21f99f5adfa", "new": "38ade74fd580b87eca5a53d6a04cf11c22e95b79f38c53885b5a8a5b78e48986", "blob": ""}, {"path": "backend/app/execution/execution_router.py", "orig": "c740a0fb99199f42255b444b12f280bb6c101e4fbc9616a8c675b4ea92736eb5", "new": "14794a18697893bf424c38acb5a546153de84f0bfc6b71259bbc1b4445a42c5b", "blob": ""}, {"path": "backend/app/execution/testkit_fake_kite.py", "orig": "afa4290b71653c6c7ef8bf03c273dc76bc6d312ab8247f829d3b3aa36611487c", "new": "bc6bcd255a9b1c18a347e59ba5a102e0d08a8fb47ea728a2fe8748be29851c81", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [         "app/engine/test_fleet_adversarial.py",
         "app/engine/test_fleet_live.py",
         "app/execution/test_broker_truth.py",
         "app/execution/test_gtt_verify_strict.py",
         "app/execution/test_execution_router_contract.py",
         "app/engine/ic/test_ic_gtt_strict.py",
         "app/engine/tma2/test_tma2_e2e.py",
         "app/engine/tma2/test_tma2_entry_paths.py",
         "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tma2/test_tma_fill_truth.py",
         "app/engine/tma2/test_tma_gap_close.py",
         "app/engine/vet/test_vet_e2e.py",
         "app/engine/vet/test_vet_manager.py",
         "app/engine/vet/test_vet_live_confirm.py",
         "app/engine/tsg/test_tsg_live_core.py",
         "app/engine/tsg/test_tsg_live_confirm.py",
         "app/engine/test_entry_fast_confirm.py"
]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_opposite_sides.py (v11.7.9 main)
if "--rollback" not in args:
    _pf = os.path.join(repo, *['backend', 'app', 'execution', 'broker_truth.py'])
    if not os.path.exists(_pf) or 'def opposite(' not in open(_pf, encoding="utf-8").read():
        die("run apply_opposite_sides.py (v11.7.9 main) first — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="gtt_monitor_proof_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, ADV_STAGE="1", SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: python3 apply_gtt_kill_list.py --allow-dirty")
say("  Undo: python3 apply_gtt_monitor_proof.py --rollback")
